Clase Nivel1
    Publico Metodo Valor() Como Entero
        Retornar 1;
    FinMetodo
FinClase

Clase Nivel2 Hereda De Nivel1
    Publico Metodo Valor() Como Entero
        Retornar Super.Valor() + 10;
    FinMetodo
FinClase

Clase Nivel3 Hereda De Nivel2
    Publico Metodo Valor() Como Entero
        Retornar Super.Valor() + 100;
    FinMetodo
FinClase

Proceso ProbarNiveles
    Definir nivel Como Entero;
    Definir objeto Como Nivel1;
    Leer nivel;
    Si nivel = 1 Entonces
        objeto <- Nuevo Nivel1();
    SiNo
        Si nivel = 2 Entonces
            objeto <- Nuevo Nivel2();
        SiNo
            objeto <- Nuevo Nivel3();
        FinSi
    FinSi
    Escribir objeto.Valor();
FinProceso
